logger = logging.getLogger()

EXCLUDE_PATHS = {"//CPUE//countFreeSrbIndex",
                 "//CPCELL//blacklistedCells",
                 "//CPCELL//ssbFrequency",
                 "//CPCELL//operationalMode",
                 "//CPCELL//plmns",
                 "//CPNRT//poolPayload",
                 "//CPNRT//poolCtrl",
                 "//CPNRT//poolPayloadRlcBundles",
                 "//l2NrtPoolList//maxNumOfPduSessionGroups",
                 "//l2NrtPoolList//maxNumOfBearerGroups",
                 "//l2NrtPoolList//rohcMaxSupportedCtx",
                 "//CPRT//maxSrbNumber",
                 "//CPRT//maxDrbNumber",
                 "//resourceType[text()='poolPayload']/..",
                 "//resourceType[text()='poolCtrl']/..",
                 "//resourceType[text()='poolPayloadRlcBundles']/..",
                 "//resourceType[text()='poolInd']/..",
                 "//bufferPoolFreeCount",
                 "//CPRT//usedHarqCount",
                 "//CPRT//storedHarqEventCount",
                 "//CPRT//rlcSduDescriptorUsingCount"}


SORT_DEFAULTS = {'l2loInfo': 'l2loPoolId',
                 'l2psInfo': 'l2psPoolId',
                 'bufferPoolFreeCount': 'poolIndex',
                 'l2hiInfo': 'l2hiPoolId',
                 'l2NrtPoolList': 'l2NrtPoolId',
                 'l2hiResource': 'resourceType'}


def get_robot_output_dir():
    """
    Returns the currently set robot builtin variable for the output directory.
    If robot is not running, None will be returned.
    This library is to be expected to be used from robot keywords.
    """
    return tl_config.get_robot_variable('${OUTPUT DIR}')


def get_nodeb_ids(node_type):
    """
    Determines all currently available gNodeBs in the testline configuration and
    returns all indices/node_ids for the configured gNodeBs.
    """
    tl = tl_config.get_testline_configuration()
    if tl is None:
        raise AssertionError("The testline configuration is not loaded within ${tl}!"
                             "unable to get node ids!")

    if node_type == 'gnb':
        if tl.gnbs:
            return [x for x, _ in enumerate(tl.gnbs)]
    elif node_type == 'enb':
        if tl.enbs:
            return [x for x, _ in enumerate(tl.enbs) if tl.enbs[x].__class__.__name__ != 'LTEEmuEnb']
    else:
        raise AssertionError("Node Type [{}] is not supported!".format(node_type))

    return []


def get_hops_and_forwarding_port(node_id=0, node_type='gnb'):
    """
    This function determines, if a hop is required to access the given nodeb.
    If a hop is needed, the configuration of the hop is returned as first element of a tuple,
    the second argument is always a forwarding port, which depends only on the given node_id.

    :param node_id: The node_id which corresponds to the index in the testline config of tl.gnbs or tl.enbs
    :param node_type: The type of nodeB, can be 'enb' or 'gnb'
    """
    tl = tl_config.get_testline_configuration()
    du_id = 0
    comu_id = 0

    if tl is None:
        # In case we have no testline config, return default port and no proxy
        return None, 15010

    nb_test_pc = tl_config.get_test_pc(node_id, node_type)

    hops = None
    forwarding_port = 15010
    if nb_test_pc.default_ssh_connection_details.addr != tl.test_pc.default_ssh_connection_details.addr:
        proxy = {'host': nb_test_pc.default_ssh_connection_details.addr,
                 'user': nb_test_pc.default_ssh_connection_details.username,
                 'password': nb_test_pc.default_ssh_connection_details.password}

        if node_type == 'gnb':
            lmp_connection = tl.gnbs[node_id].dus[du_id].airscale.common_units[comu_id].lmp_connection
        else:
            lmp_connection = tl.enbs[node_id].system_module.common_units[comu_id].lmp_connection

        hops = {'host': lmp_connection.addr,
                'user': lmp_connection.username,
                'password': lmp_connection.password,
                'proxy': proxy}

        forwarding_port = 15010 + int(node_id)

    return hops, forwarding_port


class PythonAaShellLib(AaShellLib):
    """
    This is a thin wrapper providing alias functionality around AaShellLib.
    It is needed, if taf.ccs.aashell is not used from robotframework but from python.
    """

    def __init__(self, **kwargs):
        super(PythonAaShellLib, self).__init__(**kwargs)
        self._aliases = {}

    def set_alias(self, alias, obj):
        self._aliases[alias] = obj

    def get_alias_value(self, alias):
        return self._aliases[alias]

    def _create_builin(self):
        pass


@contextmanager
def aashell_context(alias, node_type='gnb', node_id=0):
    """
    This function provides a context manager for creating the aashell cli for
    any kind of operations.

    :param alias: The alias for the taf.ccs.aashell creation
    :param node_type: The type of nodeB, can be 'enb' or 'gnb'
    :param node_id: The node_id which corresponds to the index in the testline config of tl.gnbs or tl.enbs
    """
    aashell_lib = PythonAaShellLib()
    hops, forwarding_port = get_hops_and_forwarding_port(node_id, node_type)

    try:
        aashell_lib.create_aashell_cli(name=alias, hops=hops, forwarding_port=forwarding_port)
        aashell_lib.setup(alias=alias)
    except Exception as err:
        logger.error('Exception occurred in creation of aashell_context!')
        logger.error(traceback.format_exc())
        raise AssertionError("Error in creation of AAshellContext: {}".format(err))

    try:
        yield aashell_lib
    finally:
        aashell_lib.teardown(alias=alias)


def get_resources(node_id=0, node_type='gnb', detailed=False, name=None):
    """
    This function collects the current used resources via aashell from the nodeb.

    TODO: Adapt for short format.

    :param node_type: The type of nodeB, can be 'enb' or 'gnb'
    :param node_id: The node_id which corresponds to the index in the testline configuration of tl.gnbs or tl.enbs
    """

    if tl_config.is_aic(node_type=node_type, node_id=node_id):
        return all_in_cloud.collect_resources_from_cloud(node_type=node_type, node_id=node_id)

    else:
        with aashell_context(alias='aashell_resource_usage', node_type=node_type, node_id=node_id) as aashell:
            res = aashell.get_resources_usage(name='aashell_resource_usage', detailed=detailed)
            sorted_res = aashell.sort_resources_usage(res, **SORT_DEFAULTS)
            if name:
                save_resources(sorted_res, '{}'.format(name))
            return sorted_res


def should_be_equal(resource1, resource2, exclude=None, save_to_file=None):
    """
    This function checks with help of the taf.ccs.aashell library, if the two given resources have differences.

    TODO: Save the resources and result in files constructed by output_dir and tc_name

    :param resource1: The first data for the comparison
    :param resource1: The second data for the comparison
    :param exclude: What parameters to exclude during comparison. I.e. '//bufferPoolFreeCount'
    """
    if exclude is None:
        exclude = '|'.join(EXCLUDE_PATHS)

    try:
        aashell = CheckResourcesUsage()
        aashell.should_be_equal_as_resources(resource1,
                                             resource2,
                                             exclude=exclude)
    except AssertionError:
        documentation_url = 'https://confluence.ext.net.nokia.com/pages/viewpage.action?' \
                            'pageId=1311145579#ResourceUsageCNI68640(CP)' \
                            '/CNI72046(UP)testinginET-StepsIncaseofdetecteddifferences'
        logger.warning("Provided Resources Differ!")
        logger.info("For further information visit: {}!".format(documentation_url))
        logger.info("Excluding: '{}'".format(exclude))
        logger.debug('Resources Checkpoint1 {}:'.format(json.dumps(resource1, indent=4)))
        logger.debug('Resources Checkpoint2 {}:'.format(json.dumps(resource2, indent=4)))
        log_difference(resource1, resource2, exclude, save_to_file)
        raise AssertionError("Resources Differ!")


def compare_resources(resource1, resource2, *args):
    """
    Compares the resource usage with xpath using the call of taf.ccs.aashell:
    compare_resources_usage_with_xpath. All default excludes are added to the check.

    :param resource1: The first data for the comparance
    :param resource1: The second data for the comparance
    :param args: a list of parameters with their comparison function
    """
    for excluded_path in EXCLUDE_PATHS:
        args = (excluded_path, lambda r1, r2: True) + args

    logger.info('The following paths are ignored: {}'.format(', '.join(EXCLUDE_PATHS)))

    try:
        aashell = CheckResourcesUsage()
        return aashell.compare_resources_usage_with_xpath(resource1, resource2, *args)
    except AssertionError as err:
        raise_from(AssertionError("Comparing Resources shows differing resources: {}".format(err)), err)


def get_all_resources(name=None, detailed=False):
    """
    Collects the resources of all nodebs configured in the testline configuration
    and returns them in a dictionary, With the key defining the node_type and node_id
    in the form of "gnb0" or "enb1"
    """
    nodes = [('gnb', node_id) for node_id in get_nodeb_ids('gnb')]
    nodes += [('enb', node_id) for node_id in get_nodeb_ids('enb')]

    collected_resource = {}

    for node_type, node_id in nodes:
        resource_name = None
        if name:
            resource_name = '{}_{}{}.json'.format(name, node_type, node_id)

        collected_resource[node_type + str(node_id)] = get_resources(node_id=node_id,
                                                                     node_type=node_type,
                                                                     detailed=detailed,
                                                                     name=resource_name)

    return collected_resource


def save_resources(resource, filename):
    """
    Saves the given resources in json format to the given file name.

    :param resource: The resource data to be saved.
    :param filename: The file name the data will be saved to.
    """
    with open(filename, "w") as json_write_file:
        json.dump(resource, json_write_file, indent=4)


def remove_excludes(resource, exclude):
    resource_cleaned = ResourcesUsage(resource)
    resource_cleaned.remove(exclude)
    return resource_cleaned.to_dict()


def log_difference(res1, res2, exclude=None, save_to_file=None):

    if exclude:
        resource1, resource2 = (remove_excludes(x, exclude) for x in (res1, res2))
    else:
        resource1, resource2 = res1, res2

    difference = deepdiff.DeepDiff(resource1, resource2, ignore_order=True)
    logger.error("---- START RESOURCE DIFFERENCES ----")
    logger.error(json.dumps(difference, indent=4))
    logger.error("---- END RESOURCE DIFFERENCES ----")

    if save_to_file is not None:
        with open(save_to_file, 'w') as outfile:
            json.dump(difference, outfile, indent=4)


def all_resources_should_be_equal(collected_resources1, collected_resources2):
    """
    Checks all resources collected with the keyword "Get All Resources", if there are
    resources differing. The resources must be fetched with the corresponding keyword or
    should be in form of a dictionary, where the key is describing the node, i.e. gnb0 or enb1,
    in general corresponding to the testline configuration.
    """
    resources_differ = False
    for node, resource in collected_resources1.items():
        if node in collected_resources2:
            try:
                should_be_equal(resource, collected_resources2[node])
            except AssertionError:
                logger.warning("Resources from node {} differ!".format(node))
                resources_differ = True
    if resources_differ:
        logger.warning("Found differing resources by listener!")
        raise AssertionError("Differing resources found during comparing set of resources!")
